           color: ButtonText;
           background: ButtonFace;
         }
       }
     </style>
   </head>
   <body>
     <a class="skip-link" href="#main-content">Skip to main content</a>

     <main id="main-content">
       <div class="support-layout">
         <section aria-labelledby="support-title">
           <p class="eyebrow">Support center</p>
           <h1 id="support-title">How can we help?</h1>
           <p class="intro">Send your contact details and our support team will get back to you with the next best step.</p>
         </section>

         <section class="contact-card" aria-labelledby="form-title">
           <h2 id="form-title">Contact support</h2>
           <p class="required-note"><span class="required-marker" aria-hidden="true">*</span> indicates a required field.</p>

           <form id="support-form" novalidate>
             <div class="form-field">
               <label for="full-name">Full name <span class="required-marker" aria-hidden="true">*</span></label>
               <input
                 id="full-name"
                 name="fullName"
                 type="text"
                 autocomplete="name"
                 required
                 aria-describedby="full-name-error">
               <p class="error-message" id="full-name-error">Error: Enter your full name.</p>
             </div>

             <div class="form-field">
               <label for="email">Email address <span class="required-marker" aria-hidden="true">*</span></label>
               <input
                 id="email"
                 name="email"
                 type="email"
                 autocomplete="email"
                 inputmode="email"
                 required
                 aria-describedby="email-error">
               <p class="error-message" id="email-error">Error: Enter a valid email address, like name@example.com.</p>
             </div>

             <div class="form-field">
               <label for="phone">Phone number <span>(optional)</span></label>
               <input
                 id="phone"
                 name="phone"
                 type="tel"
                 autocomplete="tel"
                 inputmode="tel"
                 aria-describedby="phone-help phone-error">
               <p class="helper-text" id="phone-help">Use 10 digits, or include a country code, for example +1 555 123 4567.</p>
               <p class="error-message" id="phone-error">Error: Enter a valid phone number, such as +1 555 123 4567, or leave this field blank.</p>
             </div>

             <p class="form-status" id="form-status" aria-live="polite"></p>
             <button type="submit">Send request</button>
           </form>
         </section>
       </div>
     </main>

     <script>
       const form = document.querySelector("#support-form");
       const statusMessage = document.querySelector("#form-status");

       const fields = {
         fullName: {
           input: document.querySelector("#full-name"),
           error: document.querySelector("#full-name-error"),
           validate(value) {
             return value.trim().length > 0;
           }
         },
         email: {
           input: document.querySelector("#email"),
           error: document.querySelector("#email-error"),
           validate(value) {
             return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim());
           }
         },
         phone: {
           input: document.querySelector("#phone"),
           error: document.querySelector("#phone-error"),
           validate(value) {
             const trimmedValue = value.trim();
             if (!trimmedValue) {
               return true;
             }

             return /^\+?[0-9][0-9\s().-]{8,}[0-9]$/.test(trimmedValue);
           }
         }
       };

       function showError(field) {
         field.input.setAttribute("aria-invalid", "true");
         field.error.classList.add("is-visible");
       }

       function clearError(field) {
         field.input.removeAttribute("aria-invalid");
         field.error.classList.remove("is-visible");
       }

       function validateField(field) {
         const isValid = field.validate(field.input.value);

         if (isValid) {
           clearError(field);
         } else {
           showError(field);
         }

         return isValid;
       }

       Object.values(fields).forEach((field) => {
         field.input.addEventListener("input", () => {
           validateField(field);
           statusMessage.classList.remove("is-visible");
           statusMessage.textContent = "";
         });

         field.input.addEventListener("blur", () => {
           validateField(field);
         });
       });

       form.addEventListener("submit", (event) => {
         event.preventDefault();

         const invalidFields = Object.values(fields).filter((field) => !validateField(field));

         statusMessage.classList.remove("is-visible");
         statusMessage.textContent = "";

         if (invalidFields.length > 0) {
           invalidFields[0].input.focus();
           return;
         }

         form.reset();
         Object.values(fields).forEach(clearError);
         statusMessage.textContent = "Thanks, your support request is ready to send.";
         statusMessage.classList.add("is-visible");
       });
     </script>
   </body>
